sys_variable_value.value:
(function execute(inputs, outputs) {
    var groupGR = new GlideRecord('sys_user_group');
    if (groupGR.get(inputs.group_id)) {
        var roleGR = new GlideRecord('sys_user_group_has_role');
        roleGR.addQuery('group', groupGR.sys_id);
        roleGR.query();

        var isResolver = false;
        while (roleGR.next()) {
            if (roleGR.role.name.toString() === 'x_1805892_reimbu_0.reimbursement_resolvers') {
                isResolver = true;
                break;
            }
        }

        outputs.isresolvergroup = isResolver;
    } else {
        outputs.isresolvergroup = false;
    }
})(inputs, outputs);

